            margin-top: 1rem;
        }

        @media (max-width: 768px) {
            .main-content {
                grid-template-columns: 1fr;
            }

            .feature-card img {
                width: 100%; /* Force image to fit */
            }
        }

        .feature-card {
            border: 1px solid #ddd;
